cards.solution:
function Persegi(sisi) {
  this.sisi = sisi;
}
Persegi.prototype.luas = function () {
  return this.sisi * this.sisi;
};
const p1 = new Persegi(4);
const p2 = new Persegi(7);
console.log(`Luas: ${p1.luas()}`);
console.log(`Luas: ${p2.luas()}`);
console.log(`Sama: ${p1.luas === p2.luas}`);
